code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for r in range(h):
        if r > 0 and h - r - 1 == r and len(set(grid[r])) == 1:
            split = ("h", r)
            break
    if split is None:
        for c in range(w):
            if c > 0 and w - c - 1 == c and len({grid[r][c] for r in range(h)}) == 1:
                split = ("v", c)
                break
    if split is None:
        raise ValueError("No centered uniform separator")
    axis, k = split
    if axis == "h":
        a, b = grid[:k], grid[k+1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    shared = {v for row in a for v in row} & {v for row in b for v in row}
    if len(shared) != 1:
        raise ValueError(f"Expected one shared panel color, got {shared}")
    color = next(iter(shared))
    return [[3 if x == color and y == color else color for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
'''
